arguments.content:
# Makefile
# Common build targets

# Default target
.DEFAULT_GOAL := all

# Variables
SRC_DIR   := src
BUILD_DIR := build
BIN_DIR   := bin

# Phony targets (not real files)
.PHONY: all build clean test install help

## all: Build everything (default)
all: build

## build: Compile/build the project
build:
	@echo "Building project..."
	@mkdir -p $(BUILD_DIR) $(BIN_DIR)
	@echo "Build complete."

## test: Run tests
test:
	@echo "Running tests..."
	@echo "Tests passed."

## install: Install the project
install: build
	@echo "Installing..."
	@echo "Install complete."

## clean: Remove build artifacts
clean:
	@echo "Cleaning build artifacts..."
	@rm -rf $(BUILD_DIR) $(BIN_DIR)
	@echo "Clean complete."

## help: Show this help message
help:
	@echo "Available targets:"
	@grep -E '^## ' Makefile | sed 's/## /  /'

arguments.new_string:
## log-env: Log key environment variables
log-env:
	@echo "=== Environment ==="
	@echo "  USER:    $${USER}"
	@echo "  HOME:    $${HOME}"
	@echo "  PWD:     $$(pwd)"
	@echo "  SHELL:   $${SHELL}"
	@echo "  MAKE:    $(MAKE)"
	@echo "  OS:      $$(uname -s)"
	@echo "==================="

